#!/usr/bin/env node
/**
 * Writes what is generated from design/system/tokens.json:
 *
 *     design/system/tokens.css            the tokens as CSS custom properties
 *     design/system/map/style.<theme>.json  the MapLibre style of the map, one per theme
 *     design/system/mark/*.svg            the sign, the application's icon and the wordmark
 *
 *     node design/tools/build-system.mjs           write them
 *     node design/tools/build-system.mjs --check   fail when one is out of date (part of `pnpm lint`)
 *
 * The tokens are the source; nobody edits the generated files. The map style
 * is written for the tile schema of ADR-0008 — the Protomaps basemap, version
 * 4 — and uses only what both MapLibre GL JS and MapLibre Native draw.
 */
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { parse } from '../system/colour.js';
import { appIcon, lockup, sign, wordmark } from '../system/mark.js';
import { linearEasing, springCurve } from '../system/motion.js';

const here = (/** @type {string} */ p) => fileURLToPath(new URL(p, import.meta.url));
const THEMES = /** @type {const} */ (['light', 'dark', 'sun']);
const SYSTEMS = /** @type {const} */ (['ios', 'android', 'web']);

/** @returns {any} */
export function readTokens() {
  return JSON.parse(readFileSync(here('../system/tokens.json'), 'utf8'));
}

// ── tokens.css ──────────────────────────────────────────────────────────────

/** A colour for a MapLibre style, which reads rgba() on every platform. @param {string} token */
function rgba(token) {
  const [r, g, b, a] = parse(token);
  return a === 1 ? token : `rgba(${r}, ${g}, ${b}, ${Number(a.toFixed(3))})`;
}

/** The value of a token that may differ by system. @param {any} token @param {string} os */
const forSystem = (token, os) => token[os] ?? token.value ?? token.ios;

/** @param {any} tokens */
export function tokensCss(tokens) {
  /** @type {string[]} */
  const out = [
    '/*',
    ' * Generated by design/tools/build-system.mjs from tokens.json. Do not edit:',
    ' * change the token and run `pnpm design:build`.',
    ' */',
    '',
  ];
  /** @param {string} selector @param {string[]} lines */
  const block = (selector, lines) =>
    out.push(`${selector} {`, ...lines.map((l) => `  ${l}`), '}', '');

  for (const theme of THEMES) {
    const selector = theme === 'light' ? ":root,\n[data-theme='light']" : `[data-theme='${theme}']`;
    const lines = Object.entries(tokens.color[theme]).map(
      ([name, value]) => `--${name}: ${value};`,
    );
    for (const [name, value] of Object.entries(tokens.elevation[theme])) {
      lines.push(`--lift-${name}: ${value};`);
    }
    const stroke = tokens.size['icon-stroke'];
    lines.push(`--icon-weight: ${theme === 'sun' ? stroke.sun : stroke.value};`);
    const blur = tokens.elevation.blur;
    for (const kind of ['regular', 'clear', 'tint']) {
      lines.push(`--blur-${kind}: ${theme === 'sun' ? 0 : blur[kind]}px;`);
    }
    const line = tokens.map.line;
    lines.push(`--line-width: ${theme === 'sun' ? line['sun-width'] : line.width};`);
    lines.push(`--line-case-width: ${theme === 'sun' ? line['sun-case'] : line.case};`);
    lines.push(`--line-glow-width: ${theme === 'sun' ? 0 : line.glow};`);
    lines.push(`--line-walked-width: ${line.walked};`);
    lines.push(`color-scheme: ${theme === 'dark' ? 'dark' : 'light'};`);
    block(selector, lines);
  }

  // What does not change with the theme.
  /** @type {string[]} */
  const fixed = [];
  for (const [name, font] of Object.entries(tokens.font)) {
    if (name === 'about') continue;
    fixed.push(`--font-${name}: '${font.family}', ${font.fallback};`);
  }
  for (const [name, value] of Object.entries(tokens.space)) {
    if (name !== 'about') fixed.push(`--space-${name}: ${value}px;`);
  }
  for (const [name, d] of Object.entries(tokens.motion.duration)) {
    fixed.push(`--dur-${name}: ${d.value}ms;`);
  }
  for (const [name, e] of Object.entries(tokens.motion.easing)) {
    fixed.push(`--ease-${name}: cubic-bezier(${e.value.join(', ')});`);
  }
  for (const [name, spring] of Object.entries(tokens.motion.spring)) {
    const curve = springCurve(spring);
    fixed.push(`--spring-${name}: ${linearEasing(curve.values)};`);
    fixed.push(`--spring-${name}-dur: ${curve.duration}ms;`);
  }
  fixed.push('--text-scale: 1;');
  block(':root', fixed);

  // The type scale answers the text size of the system, so it is worked out
  // again wherever that size is set: on the page and on every mock screen.
  /** @type {string[]} */
  const type = [
    '--ts-full: var(--text-scale);',
    '--ts-capped: min(var(--text-scale), 1.3);',
    '--ts-none: 1;',
  ];
  for (const [name, t] of Object.entries(tokens.type)) {
    if (name === 'about') continue;
    const scale = `var(--ts-${t.scales})`;
    type.push(
      `--type-${name}: ${t.style ? `${t.style} ` : ''}${t.weight} calc(${t.size}px * ${scale}) / calc(${t.line}px * ${scale}) var(--font-${t.font});`,
    );
    type.push(`--type-${name}-tracking: ${t.tracking}em;`);
  }
  block(':root,\n.screen', type);

  // What differs by system. iOS is the default, so that a page without a
  // device around it still has every value.
  for (const os of SYSTEMS) {
    /** @type {string[]} */
    const lines = [];
    for (const [name, r] of Object.entries(tokens.radius)) {
      if (name !== 'about') lines.push(`--radius-${name}: ${forSystem(r, os)}px;`);
    }
    for (const [name, s] of Object.entries(tokens.size)) {
      if (name === 'about' || name === 'icon-stroke' || name === 'reach') continue;
      lines.push(`--${name === 'target' ? 'target' : `size-${name}`}: ${forSystem(s, os)}px;`);
    }
    block(os === 'ios' ? ":root,\n[data-os='ios']" : `[data-os='${os}']`, lines);
  }
  return `${out.join('\n').trimEnd()}\n`;
}

// ── The style of the map ────────────────────────────────────────────────────

const GREEN_KINDS = [
  'park',
  'garden',
  'grass',
  'wood',
  'forest',
  'meadow',
  'scrub',
  'grassland',
  'playground',
  'pitch',
  'dog_park',
  'recreation_ground',
  'village_green',
  'allotments',
  'golf_course',
  'cemetery',
  'nature_reserve',
  'national_park',
  'zoo',
];
const MAJOR_DETAILS = [
  'motorway',
  'motorway_link',
  'trunk',
  'trunk_link',
  'primary',
  'primary_link',
];

/** @param {string} key @param {string[]} values */
const oneOf = (key, values) => ['in', ['get', key], ['literal', values]];
const notTunnel = ['!=', ['get', 'is_tunnel'], true];

/**
 * @param {any} tokens @param {'light' | 'dark' | 'sun'} theme
 * @returns {Record<string, unknown>} a MapLibre style
 */
export function mapStyle(tokens, theme) {
  const c = /** @type {Record<string, string>} */ (
    Object.fromEntries(Object.entries(tokens.color[theme]).map(([k, v]) => [k, rgba(String(v))]))
  );
  const { streets, line, buildings } = tokens.map;
  const sun = theme === 'sun';
  const mapFont = [`${tokens.font.map.family} Medium`];

  /** Width that grows with the zoom, as a street does. @param {number[]} w @param {number} [add] */
  const width = ([w13, w15, w17], add = 0) => [
    'interpolate',
    ['exponential', 1.6],
    ['zoom'],
    13,
    w13 + (w13 > 0 ? add : 0),
    15,
    w15 + add,
    17,
    w17 + add,
    19,
    w17 * 3 + add,
  ];

  const roadFilters = {
    major: [
      'any',
      ['==', ['get', 'kind'], 'highway'],
      ['all', ['==', ['get', 'kind'], 'major_road'], oneOf('kind_detail', MAJOR_DETAILS)],
    ],
    mid: ['all', ['==', ['get', 'kind'], 'major_road'], ['!', oneOf('kind_detail', MAJOR_DETAILS)]],
    minor: oneOf('kind', ['minor_road', 'other']),
    path: ['==', ['get', 'kind'], 'path'],
  };

  /** @param {'major' | 'mid' | 'minor' | 'path'} rank @param {boolean} edge */
  const road = (rank, edge) => ({
    id: `street-${rank}${edge ? '-edge' : ''}`,
    type: 'line',
    source: 'basemap',
    'source-layer': 'roads',
    ...(rank === 'path' ? { minzoom: 14 } : {}),
    filter: ['all', roadFilters[rank], notTunnel],
    layout: { 'line-cap': 'round', 'line-join': 'round' },
    paint: {
      'line-color': edge ? c['m-street-edge'] : c['m-street'],
      'line-width': width(streets[rank], edge ? 2 : 0),
    },
  });

  /** @param {string} part */
  const part = (part) => ['==', ['get', 'part'], part];
  /** @param {string} id @param {Record<string, unknown>} paint @param {string} [of] */
  const routeLine = (id, paint, of = 'ahead') => ({
    id,
    type: 'line',
    source: 'route',
    filter: part(of),
    layout: { 'line-cap': 'round', 'line-join': 'round' },
    paint,
  });

  const layers = [
    { id: 'ground', type: 'background', paint: { 'background-color': c['m-ground'] } },
    {
      id: 'green',
      type: 'fill',
      source: 'basemap',
      'source-layer': 'landuse',
      filter: oneOf('kind', GREEN_KINDS),
      paint: { 'fill-color': c['m-green'] },
    },
    {
      id: 'water',
      type: 'fill',
      source: 'basemap',
      'source-layer': 'water',
      filter: ['==', ['geometry-type'], 'Polygon'],
      paint: { 'fill-color': c['m-water'] },
    },
    {
      id: 'waterway',
      type: 'line',
      source: 'basemap',
      'source-layer': 'water',
      filter: ['==', ['geometry-type'], 'LineString'],
      layout: { 'line-cap': 'round' },
      paint: {
        'line-color': c['m-water'],
        'line-width': ['interpolate', ['linear'], ['zoom'], 12, 1, 17, 6],
      },
    },
    {
      id: 'squares',
      type: 'fill',
      source: 'basemap',
      'source-layer': 'landuse',
      filter: oneOf('kind', ['pedestrian', 'pier']),
      paint: { 'fill-color': c['m-street'] },
    },
    // Edges first, all of them, so that streets join without a seam.
    road('minor', true),
    road('mid', true),
    road('major', true),
    road('path', false),
    road('minor', false),
    road('mid', false),
    road('major', false),
    {
      id: 'rail',
      type: 'line',
      source: 'basemap',
      'source-layer': 'roads',
      filter: [
        'all',
        ['==', ['get', 'kind'], 'rail'],
        ['==', ['get', 'kind_detail'], 'rail'],
        notTunnel,
      ],
      paint: {
        'line-color': c['m-rail'],
        'line-width': ['interpolate', ['linear'], ['zoom'], 12, 1, 17, 3.2],
      },
    },
    {
      id: 'rail-ties',
      type: 'line',
      source: 'basemap',
      'source-layer': 'roads',
      minzoom: 14,
      filter: [
        'all',
        ['==', ['get', 'kind'], 'rail'],
        ['==', ['get', 'kind_detail'], 'rail'],
        notTunnel,
      ],
      paint: {
        'line-color': c['m-ground'],
        'line-width': ['interpolate', ['linear'], ['zoom'], 14, 0.6, 17, 1.6],
        'line-dasharray': [3, 3],
      },
    },
    {
      id: 'buildings',
      type: 'fill',
      source: 'basemap',
      'source-layer': 'buildings',
      minzoom: 13,
      filter: [
        'all',
        oneOf('kind', ['building', 'building_part']),
        ['==', ['geometry-type'], 'Polygon'],
      ],
      paint: {
        'fill-color': c['m-building'],
        ...(sun ? { 'fill-outline-color': c['m-wall'] } : {}),
      },
    },
    {
      id: 'places',
      type: 'fill',
      source: 'route',
      filter: part('place'),
      paint: { 'fill-color': c['m-place'] },
    },
    routeLine(
      'line-walked',
      { 'line-color': c['ink-3'], 'line-width': line.walked, 'line-opacity': 0.75 },
      'walked',
    ),
    ...(sun
      ? []
      : [
          routeLine('line-glow', {
            'line-color': c.accent,
            'line-width': line.glow,
            'line-opacity': 0.3,
            'line-blur': 6,
          }),
        ]),
    routeLine('line-case', {
      'line-color': c['line-case'],
      'line-width': sun ? line['sun-case'] : line.case,
    }),
    routeLine('line', { 'line-color': c.line, 'line-width': sun ? line['sun-width'] : line.width }),
    // The way ahead moves: the application steps `line-dasharray` in time.
    routeLine('line-march', {
      'line-color': 'rgba(255, 255, 255, 0.8)',
      'line-width': 1.6,
      'line-dasharray': [0.5, 2.5],
    }),
    {
      id: 'buildings-standing',
      type: 'fill-extrusion',
      source: 'basemap',
      'source-layer': 'buildings',
      minzoom: 15,
      filter: [
        'all',
        oneOf('kind', ['building', 'building_part']),
        ['==', ['geometry-type'], 'Polygon'],
      ],
      // Off in the plan and in the saver mode; the application turns it on with the walking camera.
      layout: { visibility: 'none' },
      paint: {
        'fill-extrusion-color': c['m-roof'],
        'fill-extrusion-height': [
          '*',
          buildings['height-scale'],
          ['coalesce', ['get', 'height'], buildings['default-height']],
        ],
        'fill-extrusion-base': [
          '*',
          buildings['height-scale'],
          ['coalesce', ['get', 'min_height'], 0],
        ],
        'fill-extrusion-opacity': buildings.opacity,
        'fill-extrusion-vertical-gradient': true,
      },
    },
    {
      id: 'street-names',
      type: 'symbol',
      source: 'basemap',
      'source-layer': 'roads',
      minzoom: 14,
      filter: oneOf('kind', ['highway', 'major_road', 'minor_road']),
      layout: {
        'symbol-placement': 'line',
        'symbol-spacing': 320,
        'text-field': ['coalesce', ['get', 'name:en'], ['get', 'name']],
        'text-font': mapFont,
        'text-size': ['interpolate', ['linear'], ['zoom'], 14, 10, 17, 13],
        'text-max-angle': 30,
        'text-letter-spacing': 0.01,
      },
      paint: {
        'text-color': sun ? c.ink : c['ink-2'],
        'text-halo-color': c['m-street'],
        'text-halo-width': 1.5,
      },
    },
    {
      id: 'marks',
      type: 'symbol',
      source: 'route',
      filter: part('mark'),
      layout: {
        'text-field': ['get', 'clock'],
        'text-font': mapFont,
        'text-size': 11,
        'text-allow-overlap': true,
      },
      paint: { 'text-color': c.ink, 'text-halo-color': c.mark, 'text-halo-width': 4 },
    },
    {
      id: 'terminus',
      type: 'circle',
      source: 'route',
      filter: part('terminus'),
      paint: {
        'circle-radius': 7,
        'circle-color': c.ink,
        'circle-stroke-color': c['m-street'],
        'circle-stroke-width': 2,
      },
    },
    {
      id: 'stops',
      type: 'circle',
      source: 'route',
      filter: part('stop'),
      paint: {
        'circle-radius': 11.5,
        'circle-color': ['match', ['get', 'state'], 'current', c.accent, 'done', c.line, c.marker],
        'circle-stroke-color': ['match', ['get', 'state'], 'current', c.marker, c.line],
        'circle-stroke-width': 2.5,
      },
    },
    {
      id: 'stop-numbers',
      type: 'symbol',
      source: 'route',
      filter: part('stop'),
      layout: {
        'text-field': ['to-string', ['get', 'order']],
        'text-font': mapFont,
        'text-size': 11,
        'text-allow-overlap': true,
        'text-ignore-placement': true,
      },
      paint: {
        'text-color': ['match', ['get', 'state'], 'done', c.marker, c['on-marker']],
      },
    },
  ];

  return {
    version: 8,
    name: `Promenade, ${theme}`,
    metadata: {
      'promenade:about':
        'Generated by design/tools/build-system.mjs from design/system/tokens.json. Do not edit.',
      'promenade:theme': theme,
      'promenade:schema': 'Protomaps basemap, version 4',
      'promenade:language':
        'Names are written with name:en. The map component puts the language of the person in its place; where OpenStreetMap has no name in that language the local name is shown (ADR-0008, point 5).',
      'promenade:name-layers': ['street-names'],
      'promenade:camera': tokens.map.camera,
      'promenade:walking':
        'With the walking camera the application shows buildings-standing and hides buildings; in the saver mode it does neither.',
      'promenade:haze':
        'The haze at the horizon is drawn by the application over the map: MapLibre Native has no sky.',
    },
    // Both are replaced by the map component with where the Route Pack or the
    // city's archive really is (ADR-0008, points 3 and 4).
    glyphs: 'glyphs/{fontstack}/{range}.pbf',
    sources: {
      basemap: {
        type: 'vector',
        url: 'pmtiles://basemap.pmtiles',
        attribution: '© OpenStreetMap',
      },
      route: { type: 'geojson', data: { type: 'FeatureCollection', features: [] } },
    },
    light: { anchor: 'viewport', color: '#ffffff', intensity: theme === 'dark' ? 0.22 : 0.3 },
    layers,
  };
}

// ── Writing, or checking that what is written is current ────────────────────

/** @param {any} tokens @returns {Record<string, string>} path → content */
export function generated(tokens) {
  /** @type {Record<string, string>} */
  const files = { [here('../system/tokens.css')]: tokensCss(tokens) };
  for (const theme of THEMES) {
    files[here(`../system/map/style.${theme}.json`)] =
      `${JSON.stringify(mapStyle(tokens, theme), null, 2)}\n`;
  }
  // The mark, drawn by the same functions as on the system's page.
  const outline = JSON.parse(readFileSync(here('../system/mark/outline.json'), 'utf8'));
  const { light, dark } = tokens.color;
  for (const variant of /** @type {const} */ (['dark', 'light', 'mono'])) {
    files[here(`../system/mark/app-icon-${variant}.svg`)] = `${appIcon(variant, tokens.color)}\n`;
  }
  files[here('../system/mark/sign.svg')] =
    `${sign({ line: light.accent, paper: light.ink }, { size: 84, title: 'Promenade' })}\n`;
  files[here('../system/mark/sign-on-dark.svg')] =
    `${sign({ line: dark.accent, paper: dark.ink }, { size: 84, title: 'Promenade' })}\n`;
  files[here('../system/mark/wordmark.svg')] = `${wordmark(outline, { fill: light.ink })}\n`;
  files[here('../system/mark/lockup.svg')] =
    `${lockup(outline, { line: light.accent, paper: light.ink, ink: light.ink })}\n`;
  files[here('../system/mark/lockup-on-dark.svg')] =
    `${lockup(outline, { line: dark.accent, paper: dark.ink, ink: dark.ink })}\n`;
  return files;
}

/** @returns {string[]} the generated files that are out of date */
export function stale() {
  const files = generated(readTokens());
  return Object.entries(files)
    .filter(([path, content]) => {
      try {
        return readFileSync(path, 'utf8') !== content;
      } catch {
        return true;
      }
    })
    .map(([path]) => path);
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (process.argv.includes('--check')) {
    const old = stale();
    if (old.length > 0) {
      console.error(
        `Out of date, run \`pnpm design:build\`:\n${old.map((p) => `  ${p}`).join('\n')}`,
      );
      process.exit(1);
    }
    console.log('Design system: generated files are current.');
  } else {
    const files = generated(readTokens());
    for (const [path, content] of Object.entries(files)) {
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, content);
    }
    console.log(`Design system: wrote ${Object.keys(files).length} files from tokens.json.`);
  }
}
